// Promotion facts (Wikidata, CC0) and free logos (Commons), generated by
// scripts/fetch-promotion-data.mjs. Hand-checked frontmatter wins.
import data from '../data/promotion-facts.json';
export interface Logo { src: string; width: number; height: number; credit: string; license: string; license_url: string | null; source: string }
export interface PromoFacts { qid: string; label: string | null; founded: string | null; dissolved: string | null; founders: string[]; owners: string[]; headquarters: string | null; country: string | null; website: string | null; logo: Logo | null }
const all = data as Record<string, PromoFacts>;
export const promoFacts = (slug: string): PromoFacts | null => all[slug] ?? null;
export const allLogos = () => Object.entries(all).filter(([, f]) => f.logo).map(([slug, f]) => ({ slug, logo: f.logo! }));
export const prettyUrl = (u: string) => u.replace(/^https?:\/\/(www\.)?/, '').replace(/\/$/, '');
